// â”€â”€ Fast Apply search/replace block parser (from Void) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// Format:
//   <<<<<<< ORIGINAL
//   ... old code ...
//   =======
//   ... new code ...
//   >>>>>>> UPDATED

export interface SearchReplaceBlock {
    original: string;
    updated: string;
}

export function extractSearchReplaceBlocks(text: string): SearchReplaceBlock[] {
    const blocks: SearchReplaceBlock[] = [];
    const pattern = /<<<<<<< ORIGINAL\n([\s\S]*?)\n?=======\n([\s\S]*?)\n?>>>>>>> UPDATED/g;
    let match: RegExpExecArray | null;
    while ((match = pattern.exec(text)) !== null) {
        blocks.push({ original: match[1], updated: match[2] });
    }
    return blocks;
}

