pub async fn hunt_api_keys(
    _state: State<'_, EditorState>,
    app: AppHandle,
    provider: String,
) -> Result<Vec<crate::hunter::HuntResult>, String> {
    use crate::domain::HuntProgress;
    
    // apiradar.live leaked-key hunting is DISABLED â€” using third-party leaked API
    // keys is a legal/business liability and not appropriate for a shipped product.
    let _ = app.emit("hunt-progress", HuntProgress { msg: format!("Leak hunting disabled for {}.", provider) });
    let leaks: Vec<crate::hunter::ApiRadarLeak> = Vec::new();
    let mut results = Vec::new();

    for leak in leaks {
         results.push(crate::hunter::HuntResult {
             provider: leak.provider,
             key: leak.redacted_key,
             key_type: "Leaked".to_string(),
             source: "ApiRadar".to_string(),
             repo_url: leak.repo_url,
             is_live: false,
             details: format!("Found in file: {}", leak.file_path),
         });
    }

    Ok(results)
}

