                };
            }
        }
    } catch { /* non-fatal */ }

    const promptConfig: SystemPromptConfig = {
        activeRoot,
        activeFile: storeState.activeEditorPath || undefined,
        openTabs: tabs.map((t: any) => ({
            path: t.path,
            language: t.language || '',
