    }
    const systemMessage = {
        role: 'system',
        content: systemContext,
        tool_calls: null,
        metadata: null,
    };

    // --- Get tool schemas for the provider ---
    let toolSchemas: any[] = [];
    if (routingProvider === 'anthropic') {
        toolSchemas = getToolSchemasAnthropic();
