      rel="stylesheet"
    />
  </head>
  <body class="overflow-hidden overflow-y-auto bg-background text-foreground transition-colors duration-300 selection:bg-primary/25 selection:text-foreground">
    <Navbar />
    <slot />
    {compactFooter ? <FooterCompact /> : <Footer />}
  </body>
  <script>
    const toggleMenu = document.querySelector("[data-toggle-nav]");
    const navbar = document.querySelector("[data-navbar]");
    const overlayNav = document.querySelector("[data-nav-overlay]");
    const closeMobileNav = () => {
      toggleMenu?.setAttribute("data-open-nav", "false");
      toggleMenu?.setAttribute("aria-expanded", "false");
      overlayNav?.setAttribute("data-is-visible", "false");
      document.body.classList.remove("!overflow-y-hidden");
      if (navbar) navbar.style.height = "0px";
    };

    const openMobileNav = () => {
      toggleMenu?.setAttribute("data-open-nav", "true");
      toggleMenu?.setAttribute("aria-expanded", "true");
      overlayNav?.setAttribute("data-is-visible", "true");
      document.body.classList.add("!overflow-y-hidden");
      if (navbar) navbar.style.height = `${navbar.scrollHeight}px`;
    };

    if (toggleMenu) {
      toggleMenu.addEventListener("click", (e) => {
        e.preventDefault();
        if (toggleMenu.getAttribute("data-open-nav") === "false") openMobileNav();
        else closeMobileNav();
      });

      overlayNav?.addEventListener("click", (e) => {
        e.preventDefault();
        closeMobileNav();
      });

      navbar?.querySelectorAll("a[href]").forEach((link) => {
        link.addEventListener("click", () => {
          if (window.matchMedia("(max-width: 1023px)").matches) closeMobileNav();
        });
      });

      window.addEventListener("resize", () => {
        if (window.matchMedia("(min-width: 1024px)").matches) {
          closeMobileNav();
          if (navbar instanceof HTMLElement) navbar.style.height = "";
        }
      });
    }
  </script>
  <script>
    // Global scroll-reveal â€” re-armed on every view-transition navigation.
