    };
    format!("{}://{}", scheme, hostish)
        .trim_end_matches('/')
        .to_string()
}

fn ollama_should_infer_scheme(s: &str) -> bool {
    let head = s
        .split('/')
        .next()
        .unwrap_or("")
        .split('?')
        .next()
        .unwrap_or("")
        .trim_start_matches('/');
    if head.is_empty() {
        return false;
    }
    let lower = head.to_lowercase();
    if lower.starts_with("localhost") {
        return true;
    }
    // IPv4 / numeric host
    if head
        .chars()
        .next()
        .map(|c| c.is_ascii_digit())
        .unwrap_or(false)
        || head.starts_with('[')
    {
        return head.contains('.') || head.contains(':');
    }
    if !head.contains('.') {
        return false;
    }
    let labels: Vec<&str> = head.split('.').filter(|p| !p.is_empty()).collect();
    if labels.len() < 2 {
        return false;
    }
    labels.last().map_or(false, |tld| tld.len() >= 2)
}

