const VERIFY_URL = "https://challenges.cloudflare.com/turnstile/v0/siteverify";

export interface TurnstileResult {
  ok: boolean;
  enforced: boolean;        // false when no secret configured (fail-open)
  errors?: string[];
}

export async function verifyTurnstile(token: string, ip?: string): Promise<TurnstileResult> {
  const secret = cfg("TURNSTILE_SECRET_KEY");
  if (!secret) return { ok: true, enforced: false }; // not configured yet â†’ allow
  if (!token) return { ok: false, enforced: true, errors: ["missing-token"] };

  const form = new URLSearchParams();
  form.set("secret", secret);
  form.set("response", token);
  if (ip) form.set("remoteip", ip);

  try {
    const res = await fetch(VERIFY_URL, { method: "POST", body: form });
    const b = await res.json().catch(() => ({}));
    return { ok: !!b.success, enforced: true, errors: b["error-codes"] };
  } catch {
    // Network failure verifying â€” fail closed so an outage can't be a bypass.
    return { ok: false, enforced: true, errors: ["verify-network-error"] };
  }
}

/** Client IP from Netlify / Cloudflare headers. */
export function clientIp(req: Request): string {
  return (
    req.headers.get("x-nf-client-connection-ip") ||
    req.headers.get("cf-connecting-ip") ||
    (req.headers.get("x-forwarded-for") || "").split(",")[0].trim() ||
    ""
  );
}

